import { API_BASE_URL } from '../utils/api';

export const loginSalesStaff = async (credentials) => {
  try {
    // 發送登入請求到後端進行驗證
    const response = await fetch(`${API_BASE_URL}/api/auth/login`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        identifier: credentials.username,
        password: credentials.password
      })
    });
    
    if (!response.ok) {
      const errorData = await response.json().catch(() => ({ message: '登入失敗' }));
      throw new Error(errorData.message || '用戶名或密碼錯誤');
    }
    
    const authData = await response.json();
    
    if (!authData.jwt || !authData.user) {
      throw new Error('認證失敗：無效的回應格式');
    }
    
    // 檢查用戶角色權限
    const userRole = authData.user.role?.type || 'authenticated';
    if (!['staff', 'manager', 'authenticated'].includes(userRole)) {
      throw new Error('權限不足：無法訪問系統');
    }
    
    // 創建安全的用戶對象
    const secureUser = {
      id: authData.user.id,
      username: authData.user.username,
      email: authData.user.email,
      name: authData.user.name || authData.user.username,
      role: userRole,
      jwt: authData.jwt
    };
    
    // 安全儲存到 localStorage
    localStorage.setItem('token', authData.jwt);
    localStorage.setItem('user', JSON.stringify(secureUser));
    localStorage.setItem('salesStaff', JSON.stringify(secureUser)); // 兼容性
    
    return {
      jwt: authData.jwt,
      user: secureUser
    };
  } catch (error) {
    // 清除可能的錯誤狀態
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    localStorage.removeItem('salesStaff');
    throw error;
  }
};

export const checkAuth = () => {
  const token = localStorage.getItem('token');
  const user = JSON.parse(localStorage.getItem('user') || 'null');
  
  return {
    isAuthenticated: !!token && !!user,
    user,
    token
  };
};

export const logout = () => {
  localStorage.removeItem('token');
  localStorage.removeItem('user');
  localStorage.removeItem('salesStaff');
  window.location.href = '/#/crm/login';
}; 